/// <summary>
/// Extension classe for <c>SalesTableType</c> class
/// </summary>
[ExtensionOf(classStr(SalesTableType))]
public final class METSalesTableType_Extension
{
}

Method.Source:
    /// <summary>
    /// Update Extract status
    /// </summary>
    public void metUpdateExtractStatus()
    {
        SalesLine       metSalesLine;
        METSalesLine    metMETSalesLine;

        select firstonly RecId from metSalesLine
            where metSalesLine.SalesId == salesTable.Salesid
            && metSalesLine.SalesStatus != SalesStatus::Canceled
            join metMETSalesLine where metMETSalesLine.SalesLine == metSalesLine.RecId
            &&  metMETSalesLine.OrderExtractStatus != METOrderExtractStatus::Extracted;

        ttsbegin;
        
        salesTable.reread();
        salesTable.METOrderExtractStatus = metSalesLine.RecId ? METOrderExtractStatus::Open : METOrderExtractStatus::Extracted;
        salesTable.SkipUpdate   = InterCompanySkipUpdate::Both;
        salesTable.update();

        ttscommit;
  
    }

    /// <summary>
    /// May confirmation be updated
    /// </summary>
    /// <returns>True or false</returns>
    boolean mayConfirmationBeUpdated()
    {        
        boolean             ok = next mayConfirmationBeUpdated();
        METCustParameters   METCustParameters = METCustParameters::Find();
        
        //CB175-SalesConfirmation-start
        if (METCustParameters.IncludeCancelledLines)
        //CB175-SalesConfirmation-end
        {
            ok = (!(salesTable.SalesStatus  == SalesStatus::Invoiced ||
                SalesTable.SalesStatus  == SalesStatus::Delivered) &&
                (salesTable.mcrOrderStopped == NoYes::No ||
                !isConfigurationkeyEnabled(configurationKeyNum(MCRCallCenter)))
                    );
        }

        return ok;

    }
